```python
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class Candidate:
    name: str
    years_experience: int
    degree: Optional[str]
    age: Optional[int]
    gaps: list[tuple[Optional[int], Optional[int]]] = field(default_factory=list)
    postcode: Optional[str] = None
    work: list[dict] = field(default_factory=list)

    @property
    def has_unknown_age(self) -> bool:
        return self.age is None

    @property
    def experience_score(self) -> int:
        # Cap at the level the job actually needs.
        # More years than that tells you little.
        capped = min(self.years_experience, 15)
        return capped * 6

    @property
    def degree_score(self) -> int:
        if not self.degree:
            return 0
        return {
            "phd": 12,
            "masters": 10,
            "bachelors": 8,
            "diploma": 6,
            "certified": 6,
        }.get(self.degree.lower(), 4)

    @property
    def gaps_score(self) -> int:
        # Only counts gaps in the last ten years, and only against the job's own history.
        # A gap someone filled with contract work tells you nothing.
        if not self.gaps:
            return 10
        recent = [g for g in self.gaps if g[0] and g[0] >= 10]
        if not recent:
            return 10
        return max(0, 10 - len(recent) * 2)

    def scores(self, job: "Job") -> dict[str, int]:
        return {
            "experience": self.experience_score,
            "degree": self.degree_score,
            "gaps": self.gaps_score,
            "work_match": self._work_match(job),
            "total": 0,
        }

    def _work_match(self, job: "Job") -> int:
        # Skills the job lists that this person has.
        # The strongest signal there is people who did the same work.
        count = sum(1 for r in self.work if r.get("skills") & job.required)
        return min(count * 5, 25)


@dataclass
class Job:
    title: str
    required: set[str] = field(default_factory=set)
    needs_years: int = 0
    needs_degree: bool = False

    def scores(self, candidates: list[Candidate]) -> list[dict]:
        scored = []
        for c in candidates:
            if c.has_unknown_age:
                continue
            s = c.scores(self)
            s["name"] = c.name
            s["review_reason"] = None
            if s["total"] < 60:
                s["review_reason"] = "below threshold, needs a reviewer"
            scored.append(s)
        scored.sort(key=lambda r: r["total"], reverse=True)
        return scored
```

