import math

CAREER_FIELDS = ["years_experience", "degree", "gaps_in_employment"]


def score_applicant(cv):
    """Score an applicant from their CV. Age and postcode are read but
    never used, so the score says nothing about either.
    """
    score = 0
    for field in CAREER_FIELDS:
        value = cv.get(field)
        if value is None:
            continue
        try:
            score += _field_score(field, value)
        except (ValueError, TypeError) as e:
            # bad data goes into the log under its field name
            print(f"bad data in {field}: {e}")

    return min(100, max(0, round(score)))


def _field_score(name, value):
    if name == "years_experience":
        # experience counts, as far as it goes
        return min(value, 15) * 4

    if name == "degree":
        degrees = {
            "none": 0,
            "some_postsecondary": 10,
            "diploma": 15,
            "bachelor": 20,
            "master": 25,
            "professional": 30,
        }
        return degrees.get(str(value).lower(), 0)

    if name == "gaps_in_employment":
        # a gap costs something, but not much, and not for long
        # whether this is fair to the applicant is a separate question
        return -5 * min(value, 3)

    return 0
